const raw = $input.first()?.json ?? {};
const body = raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body) ? raw.body : raw;
const fail = (message) => [{ json: { route: 'error', error: message } }];
const action = typeof body.action === 'string' ? body.action.trim() : '';

if (action === 'cities') return [{ json: { route: action, action } }];

if (action === 'coverage') {
  const cityRaw = body.cityId;
  const subtotalRaw = body.subtotal;
  const cityId = Number(cityRaw);
  const subtotal = Number(subtotalRaw);
  const cityValid = (typeof cityRaw === 'number' || (typeof cityRaw === 'string' && /^\d+$/.test(cityRaw.trim()))) && Number.isSafeInteger(cityId) && cityId > 0;
  const subtotalTypeValid = typeof subtotalRaw === 'number' || (typeof subtotalRaw === 'string' && /^\d+(?:\.\d{1,2})?$/.test(subtotalRaw.trim()));
  const subtotalValid = subtotalTypeValid && Number.isFinite(subtotal) && subtotal >= 0 && Math.abs(subtotal * 100 - Math.round(subtotal * 100)) < 1e-7;
  if (!cityValid || !subtotalValid) return fail('cityId y subtotal deben ser válidos.');
  return [{ json: { route: action, action, cityId, subtotal } }];
}

if (action === 'description') {
  const name = typeof body.name === 'string' ? body.name.trim() : '';
  const category = typeof body.category === 'string' ? body.category.trim() : '';
  const features = body.features === undefined ? [] : body.features;
  if (!name || name.length > 200 || !category || category.length > 120 || !Array.isArray(features) || features.length > 8 || features.some(x => typeof x !== 'string' || !x.trim() || x.trim().length > 150)) {
    return fail('name, category y features deben cumplir el contrato.');
  }
  return [{ json: { route: action, action, name, category, features: features.map(x => x.trim()) } }];
}

if (action === 'recommend') {
  if (!Array.isArray(body.items) || body.items.length < 1 || body.items.length > 30) return fail('items debe contener entre 1 y 30 productos del carrito.');
  const items = [];
  for (const item of body.items) {
    const product = item?.product && typeof item.product === 'object' ? item.product : {};
    const idRaw = item?.productId ?? product.id;
    const nameRaw = item?.name ?? product.name;
    const productId = Number(idRaw);
    const name = typeof nameRaw === 'string' ? nameRaw.trim() : '';
    if (!Number.isSafeInteger(productId) || productId < 1 || !name || name.length > 200) return fail('Cada artículo debe tener un productId y nombre válidos.');
    items.push({
      productId,
      name,
      size: typeof (item?.size ?? product.size) === 'string' ? (item.size ?? product.size).trim().slice(0, 40) : '',
      color: typeof (item?.color ?? product.color) === 'string' ? (item.color ?? product.color).trim().slice(0, 60) : ''
    });
  }
  return [{ json: { route: action, action, items } }];
}

return fail('La acción solicitada no está permitida.');

const response = $input.first()?.json ?? {};
const payload = response.body ?? response;
const rows = Array.isArray(payload) ? payload : payload.data;
if (!Array.isArray(rows)) throw new Error('Catalog response invalid');

const products = rows.filter(p =>
  p && (!p.estado || p.estado === 'publicado') && Number.isSafeInteger(Number(p.id)) && Number(p.id) > 0 && typeof (p.name ?? p.nombre) === 'string'
);
const categoriesOf = p => {
  const value = p.categories ?? p.categorias;
  if (Array.isArray(value)) return value.map(c => typeof c === 'string' ? c.slice(0, 80) : String(c?.name ?? c?.nombre ?? '').slice(0, 80));
  return typeof value === 'string' ? [value.slice(0, 80)] : [];
};
const catalogForModel = products.map(p => ({ id: Number(p.id), name: String(p.name ?? p.nombre).slice(0, 200), categories: categoriesOf(p) }));
if (!products.length) return [{ json: { ready: false, error: 'No hay productos publicados disponibles para recomendar.' } }];

const cart = $('Validar solicitud').first().json.items;
const prompt = [
  'Recomienda hasta cuatro productos del catálogo que complementen este carrito.',
  'Usa únicamente IDs que aparecen en el catálogo. No inventes productos ni afirmes precios, stock o características.',
  'Devuelve únicamente JSON válido con la forma {"ids":[números]}.',
  'Carrito: ' + JSON.stringify(cart),
  'Catálogo: ' + JSON.stringify(catalogForModel)
].join('\n');
return [{ json: { ready: true, prompt, catalog: products } }];

const r = $('Validar solicitud').first().json;
const prompt = [
  'Escribe una descripción comercial breve en español para una tienda costarricense de ropa y equipo de Judo y BJJ.',
  'Nombre: ' + JSON.stringify(r.name),
  'Categoría: ' + JSON.stringify(r.category),
  'Datos confirmados: ' + JSON.stringify(r.features),
  'No inventes materiales, certificaciones, origen, rendimiento, medidas, compatibilidad ni otras especificaciones ausentes.',
  'Si los datos son escasos, redacta una descripción general sin afirmaciones técnicas.',
  'Devuelve únicamente JSON válido con la forma {"description":"texto"}.'
].join('\n');
return [{ json: { task: 'description', prompt } }];

const raw = $input.first()?.json ?? {};
const source = $('Validar solicitud').first().json;
const text = raw.output ?? raw.text ?? raw.response;
const fail = () => [{ json: { ok: false, data: null, error: 'El asistente no pudo generar una respuesta válida.' } }];
const parse = value => {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  const cleaned = value.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(cleaned); } catch {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try { return JSON.parse(match[0]); } catch { return null; }
  }
};
const result = parse(text);
if (!result || Array.isArray(result) || typeof result !== 'object') return fail();

if (source.action === 'description') {
  const description = typeof result.description === 'string' ? result.description.trim() : '';
  if (description.length < 12 || description.length > 1200) return fail();
  return [{ json: { ok: true, data: { description }, error: null } }];
}

if (!Array.isArray(result.ids)) return fail();
const prepared = $('Preparar recomendación').first().json;
const allowed = new Map(prepared.catalog.map(p => [Number(p.id), p]));
const inCart = new Set(source.items.map(item => Number(item.productId)));
const ids = [...new Set(result.ids.map(Number).filter(id => Number.isSafeInteger(id) && allowed.has(id) && !inCart.has(id)))].slice(0, 4);
return [{ json: { ok: true, data: { products: ids.map(id => allowed.get(id)) }, error: null } }];

const j = $input.first()?.json ?? {};
const fail = () => [{ json: { ok: false, data: null, error: 'No se pudo cotizar el envío.' } }];
if (j.error || j.statusCode >= 400) return fail();
const response = j.body ?? j;
const data = response.data ?? response;
if (!data || typeof data.covered !== 'boolean' || typeof data.freeShipping !== 'boolean' || typeof data.message !== 'string') return fail();

const threshold = Number(data.freeShippingThreshold);
if (data.freeShippingThreshold === null || data.freeShippingThreshold === '' || !Number.isFinite(threshold) || threshold < 0) return fail();
let shippingCost;
if (data.covered === false && (data.shippingCost === null || data.shippingCost === 0 || data.shippingCost === '0')) {
  shippingCost = 0;
} else {
  shippingCost = Number(data.shippingCost);
  if (data.shippingCost === null || data.shippingCost === '' || !Number.isFinite(shippingCost) || shippingCost < 0) return fail();
}

return [{ json: { ok: true, data: { ...data, shippingCost, freeShippingThreshold: threshold }, error: null } }];
